; abs.asm -- chapter 11: the size of a signed byte, with a jump and without
; generated by gen11.py
        INCLUDE "msx.inc"
        OUTPUT "abs.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
ABSJ    EQU $D000               ; 256 answers of absj
ABSN    EQU $D100               ; and of absn
; The size of a signed byte, for all 256 values: with a jump (absj) and with
; no jump (absn).
init:   di
        ld sp, SYS_AREA
        ld hl, ABSJ
        ld d, 0                 ; D: 0 to 255
j1:     ld a, d
j2:     call absj
j3:     ld (hl), a
        inc hl
        inc d
        jr nz, j1
        ld hl, ABSN
n1:     ld a, d
n2:     call absn
n3:     ld (hl), a
        inc hl
        inc d
        jr nz, n1
stop:   jr stop

; absj: A = the size of A, taken as signed, with a jump
absj:   or a                    ; S from A
        jp p, aj1               ; 0 or positive: as it is
        neg                     ; negative: turned round
aj1:    ret

; absn: the same with no jump. Uses B and C.
absn:   ld b, a
        add a, a                ; the sign into the carry
        sbc a, a                ; $00, or $FF for a negative number
        ld c, a
        xor b                   ; negative: every bit turned over ...
        sub c                   ; ... and 1 added, since 0 - $FF is 1
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
